let g_unRejectedMutationCount = 0;

function GetFunctionSource(strName, strSource) {
	const strEscapedName = strName.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
	const DefinitionPattern = new RegExp("^(\\t+)(?:bool|void|v8::(?:Maybe)?Local<v8::(?:Object|Array|Value)>) " + strEscapedName + "\\([^\\n;{}]*\\)(?: noexcept)?(?: try)? \\{", "m");
	const vecMatch = DefinitionPattern.exec(strSource);
	g_Assert.ok(vecMatch, "Missing native definition: " + strName);

	const ClosingPattern = new RegExp("^" + vecMatch[1] + "\\}$", "gm");
	ClosingPattern.lastIndex = vecMatch.index + vecMatch[0].length;
	const vecClosingMatch = ClosingPattern.exec(strSource);
	g_Assert.ok(vecClosingMatch && (vecClosingMatch.index > vecMatch.index), "Missing native function end: " + strName);

	return strSource.slice(vecMatch.index, vecClosingMatch.index + vecClosingMatch[0].length);
}

function VerifyExtractorContracts() {
	// The prototype and earlier call are deliberate negative extractor fixtures.
	const strPrototype = "\tbool NativeValueExtractorProbe();\n";
	const strCaller = "\tbool NativeValueCaller() {\n\t\tif (NativeValueExtractorProbe()) {\n\t\t\treturn false;\n\t\t}\n\n\t\treturn true;\n\t}\n";
	const strDefinition = "\tbool NativeValueExtractorProbe() {\n\t\treturn true;\n\t}";
	g_Assert.equal(GetFunctionSource("NativeValueExtractorProbe", strPrototype + strCaller + strDefinition + "\n"), strDefinition);
	g_Assert.throws(() => GetFunctionSource("NativeValueExtractorProbe", strPrototype + strCaller), g_Assert.AssertionError);

	const strMaybePrototype = "\tv8::MaybeLocal<v8::Object> NativeValueExtractorProbe();\n";
	const strMaybeDefinition = "\tv8::MaybeLocal<v8::Object> NativeValueExtractorProbe() {\n\t\treturn {};\n\t}";
	g_Assert.equal(GetFunctionSource("NativeValueExtractorProbe", strMaybePrototype + strCaller + strMaybeDefinition + "\n"), strMaybeDefinition);
	g_Assert.throws(() => GetFunctionSource("NativeValueExtractorProbe", strMaybePrototype + strCaller), g_Assert.AssertionError);
}

function VerifyContracts(strSource) {
	for (const vecContract of g_vecSourceContracts) {
		g_Assert.ok(strSource.includes(vecContract[0]), "Native source must retain: " + vecContract[0]);
	}

	for (const vecContract of g_vecContracts) {
		g_Assert.ok(GetFunctionSource(vecContract[0], strSource).includes(vecContract[1]), vecContract[0] + " must retain: " + vecContract[1]);
	}

	const strPeer = GetFunctionSource("SetKeyValuesNextKeyCallback", strSource);
	const nPrepareIndex = strPeer.indexOf("CollectKeyValuesHierarchy(pPreviousNextKeyValues, vecPreviousNextHierarchy);");
	const nLinkIndex = strPeer.indexOf("pKeyValues->SetNextKey(pNextKeyValues);");
	const nHandoffIndex = strPeer.indexOf("itKeyValuesRecord->second.m_bOwnsKeyValues = false;");
	const nEraseIndex = strPeer.indexOf("EraseCollectedKeyValuesRecords(vecPreviousNextHierarchy);");
	const nReleaseIndex = strPeer.indexOf("pPreviousNextKeyValues->deleteThis();");
	g_Assert.ok((nPrepareIndex < nLinkIndex) && (nLinkIndex < nHandoffIndex) && (nHandoffIndex < nEraseIndex) && (nEraseIndex < nReleaseIndex), "Prepare before peer mutation and transfer ownership before detached-tree invalidation/release");

	const strFloat = GetFunctionSource("GetFiniteFloatFromValue", strSource);
	g_Assert.ok(strFloat.indexOf("std::fabs(dblNumberValue)") < strFloat.indexOf("static_cast<float>(dblNumberValue)"), "Reject out-of-range doubles before narrowing");

	for (const strName of ["CreateRGBAColorCallback", "MakeVectorObject", "MakeMathVectorObject", "MakeQAngleObject", "MakeQuaternionObject", "NormalizeVectorCallback", "GetDirectionVectorsFromAngleCallback", "GetPerpendicularVectorsFromVectorCallback"]) {
		g_Assert.ok(!/\bSet(?:Integer|Number|Value)\(/.test(GetFunctionSource(strName, strSource)), "New owned values must not invoke inherited setters: " + strName);
	}

	g_Assert.ok(strSource.indexOf(GetFunctionSource("SetRecordProperty", strSource)) < strSource.indexOf(GetFunctionSource("MakeVectorObject", strSource)), "Define the own-property helper before its first value factory");

	const strQuaternion = GetFunctionSource("GetQuaternionComponentsFromValue", strSource);
	const strCommit = "QuaternionComponentsOut = { flX, flY, flZ, flW };";
	g_Assert.equal(strQuaternion.split(strCommit).length - 1, 2, "Commit quaternion outputs once per successful input representation");
	g_Assert.ok(strQuaternion.indexOf(strCommit) > strQuaternion.indexOf("kWComponentIndex, pszUsage, flW)"), "Validate all array components before committing quaternion outputs");
	g_Assert.ok(strQuaternion.lastIndexOf(strCommit) > strQuaternion.indexOf("\"W\", nullptr, pszUsage, flW)"), "Validate all object components before committing quaternion outputs");

	const strMatrix = GetFunctionSource("GetMatrixValuesFromValue", strSource);
	const strMatrixCommit = "std::copy_n(arrStagedMatrixValues.data(), unMatrixElementCount, pflMatrixValuesOut);";
	const strMatrixValidation = "GetFiniteFloatFromValue(pIsolate, LocalContext, LocalComponentValue, pszErrorMessage, arrStagedMatrixValues[unElementIndex])";
	g_Assert.equal(strMatrix.split(strMatrixCommit).length - 1, 2, "Commit matrix outputs once per fully validated representation");
	g_Assert.equal(strMatrix.split(strMatrixValidation).length - 1, 2, "Both matrix representations must retain finite component validation");
	g_Assert.ok(strMatrix.indexOf(strMatrixCommit) > strMatrix.indexOf(strMatrixValidation), "Validate every flat component before committing matrix output");
	g_Assert.ok(strMatrix.lastIndexOf(strMatrixCommit) > strMatrix.lastIndexOf(strMatrixValidation), "Validate every nested component before committing matrix output");
	g_Assert.match(strMatrix, /if \(!LocalMatrixArray->Get\(LocalContext, unRowIndex\)\.ToLocal\(&LocalRowValue\)\) \{\n\t+return false;\n\t+\}/, "Preserve the original nested-row getter exception");
	g_Assert.ok(!/->Set\(/.test(GetFunctionSource("MakeMatrixArray", strSource)), "Fresh matrix row/component indexes must bypass inherited setters");
}

VerifyExtractorContracts();

VerifyContracts(g_strSource);

for (const vecMutation of g_vecMutations) {
	const strOriginal = GetFunctionSource(vecMutation[0], g_strSource);
	g_Assert.ok(strOriginal.includes(vecMutation[1]), "Missing mutation anchor Function=" + vecMutation[0] + " Source=" + JSON.stringify(vecMutation[1]));
	g_Assert.equal(g_strSource.indexOf(strOriginal), g_strSource.lastIndexOf(strOriginal), "Mutation requires one actual definition: " + vecMutation[0]);

	const strMutated = strOriginal.replace(vecMutation[1], () => vecMutation[2]);
	g_Assert.notEqual(strMutated, strOriginal, "Mutation must change its definition: " + vecMutation[0]);

	const strMutatedSource = g_strSource.replace(strOriginal, () => strMutated);
	g_Assert.notEqual(strMutatedSource, g_strSource, "Mutation must reach the actual source: " + vecMutation[0]);
	g_Assert.throws(() => VerifyContracts(strMutatedSource), g_Assert.AssertionError, "Reject regression: " + vecMutation[0]);
	g_unRejectedMutationCount += 1;
}

for (const vecContract of g_vecSourceContracts) {
	g_Assert.equal(g_strSource.split(vecContract[0]).length, 2, "Require one actual native macro definition");
	const strMutatedSource = g_strSource.replace(vecContract[0], () => vecContract[1]);
	g_Assert.notEqual(strMutatedSource, g_strSource, "Macro mutation must change the native source");
	g_Assert.throws(() => VerifyContracts(strMutatedSource), g_Assert.AssertionError, "Reject ordinary native macro writes");
	g_unRejectedMutationCount += 1;
}

console.log("pure native value contracts passed (" + (g_vecContracts.length + g_vecSourceContracts.length) + " source contracts, ordering/ownership checks, " + g_unRejectedMutationCount + " negative regressions; source-only checks do not execute V8 or SDK calls).");
